def balance(events):
    total = 0
    seen = {}
    remaining = {}
    for event in events:
        amount = event["amount"]
        kind = event["kind"]
        if not isinstance(amount, int) or isinstance(amount, bool) or amount < 0:
            raise ValueError("amount must be nonnegative integer cents")
        if kind not in ("charge", "refund"):
            raise ValueError("invalid event kind")

        event_id = event["id"]
        if event_id in seen:
            if seen[event_id] != event:
                raise ValueError("conflicting duplicate event ID")
            continue

        if kind == "charge":
            remaining[event_id] = amount
            total += amount
        else:
            if "charge_id" not in event or event["charge_id"] not in remaining:
                raise ValueError("refund must reference an earlier charge")
            charge_id = event["charge_id"]
            if amount > remaining[charge_id]:
                raise ValueError("refund exceeds charge amount")
            remaining[charge_id] -= amount
            total -= amount
        seen[event_id] = dict(event)
    return total

