import unittest

from ledger import balance


def charge(event_id, amount):
    return {"id": event_id, "kind": "charge", "amount": amount}


def refund(event_id, amount, charge_id):
    return {
        "id": event_id,
        "kind": "refund",
        "amount": amount,
        "charge_id": charge_id,
    }


class LedgerTests(unittest.TestCase):
    def test_empty_and_zero_amounts(self):
        self.assertEqual(balance([]), 0)
        self.assertEqual(balance([charge("c", 0), refund("r", 0, "c")]), 0)

    def test_partial_and_full_refunds_with_multiple_charges(self):
        events = [
            charge("c1", 100), charge("c2", 50),
            refund("r1", 40, "c1"), refund("r2", 60, "c1"),
            refund("r3", 10, "c2"),
        ]
        self.assertEqual(balance(iter(events)), 40)

    def test_identical_duplicates_count_once(self):
        c = charge("c", 100)
        r = refund("r", 60, "c")
        self.assertEqual(balance([c, dict(c), r, dict(r)]), 40)

    def test_conflicting_duplicate_ids(self):
        cases = [
            [charge("c", 100), charge("c", 101)],
            [charge("c", 100), refund("c", 10, "c")],
            [charge("c1", 100), charge("c2", 100),
             refund("r", 10, "c1"), refund("r", 10, "c2")],
        ]
        for events in cases:
            with self.subTest(events=events), self.assertRaises(ValueError):
                balance(events)

    def test_invalid_amounts_on_charges_and_refunds(self):
        for amount in [-1, True, False, 1.0, 0.0, "10", None]:
            for kind in ["charge", "refund"]:
                event = charge("bad", amount) if kind == "charge" else refund("bad", amount, "c")
                with self.subTest(amount=amount, kind=kind), self.assertRaises(ValueError):
                    balance([charge("c", 100), event])

    def test_invalid_kind(self):
        for kind in ["payment", "", None]:
            with self.subTest(kind=kind), self.assertRaises(ValueError):
                balance([{"id": "x", "kind": kind, "amount": 10}])

    def test_refund_requires_earlier_charge(self):
        cases = [
            [refund("r", 1, "missing")],
            [refund("r", 1, "c"), charge("c", 10)],
            [charge("c", 10), refund("r1", 1, "c"), refund("r2", 1, "r1")],
            [charge("c", 10), {"id": "r", "kind": "refund", "amount": 1}],
        ]
        for events in cases:
            with self.subTest(events=events), self.assertRaises(ValueError):
                balance(events)

    def test_over_refund_single_cumulative_and_per_charge(self):
        cases = [
            [charge("c", 10), refund("r", 11, "c")],
            [charge("c", 10), refund("r1", 6, "c"), refund("r2", 5, "c")],
            [charge("c1", 10), charge("c2", 100), refund("r", 11, "c1")],
        ]
        for events in cases:
            with self.subTest(events=events), self.assertRaises(ValueError):
                balance(events)

    def test_duplicate_charge_does_not_reset_refund_limit(self):
        c = charge("c", 10)
        with self.assertRaises(ValueError):
            balance([c, refund("r1", 6, "c"), dict(c), refund("r2", 5, "c")])

    def test_invalid_duplicate_amount_is_not_hidden_by_numeric_equality(self):
        for amount in [True, 1.0]:
            with self.subTest(amount=amount), self.assertRaises(ValueError):
                balance([charge("c", 1), charge("c", amount)])
